.dm-ste{width:100%;max-width:440px;margin:0 auto;padding:6px;display:flex;flex-direction:column}
.dm-ste-h{display:flex;flex-direction:column;padding:var(--dm-s-2) 10px 10px;border-bottom:1px solid var(--dm-line)}
.dm-ste-h b{font-weight:500;font-size:14px}
.dm-ste-st{font-size:12.5px}
.dm-ste-steps{list-style:none;margin:0;padding:var(--dm-s-1) 0}
.dm-ste-s{display:flex;align-items:center;gap:10px;min-height:44px;padding:5px 10px;border-radius:10px;font-size:13px}
.dm-ste-g{width:16px;height:16px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.dm-ste-g .dm-spin{width:11px;height:11px;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-ste-s.dm-done .dm-ste-g{color:var(--dm-ok)}
.dm-ste-t{flex:1;min-width:0;display:flex;flex-direction:column}
.dm-ste-t b{font-weight:500}
.dm-ste-t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-ste-s.dm-queued .dm-ste-t b{color:var(--dm-fg2)}
.dm-ste-log{display:flex;flex-direction:column;gap:var(--dm-s-2);padding:2px var(--dm-s-1) 10px}
.dm-ste-log:empty{display:none}
/* what you sent, on the right, with whether it is waiting or applied */
.dm-ste-me{align-self:flex-end;max-width:85%;display:flex;flex-direction:column;align-items:flex-end;gap:var(--dm-s-1)}
.dm-ste-me p{margin:0;padding:7px var(--dm-s-3);border-radius:14px 14px var(--dm-r-xs) 14px;background:var(--dm-chip);font-size:13px;line-height:1.45}
.dm-ste-q{display:inline-flex;align-items:center;gap:5px;font-size:12px;color:var(--dm-muted)}
.dm-ste-q .dm-spin{width:9px;height:9px}
.dm-ste-q svg{color:var(--dm-ok)}
/* what the agent said back; a heads-up is amber, with white buttons, until you answer it */
.dm-ste-ag{display:flex;gap:10px;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-row);font-size:13px;line-height:1.45}
.dm-ste-ag>svg{flex:none;margin-top:3px;color:var(--dm-accent-fg,var(--dm-accent))}
.dm-ste-ag.dm-warn{background:var(--dm-warn-bg)}
.dm-ste-ag.dm-warn>svg{color:var(--dm-warn)}
.dm-ste-ag .dm-t{flex:1;min-width:0;display:flex;flex-direction:column;gap:var(--dm-s-2)}
.dm-ste-ag p{margin:0}
.dm-ste-acts{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:6px}
.dm-ste-ag .dm-pill.dm-ghost{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.dm-ste-ag .dm-pill.dm-ghost:hover{box-shadow:var(--dm-shadow-pop)}}
.dm-ste-ag .dm-muted{font-size:12px}
.dm-ste-sum{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-ok-bg);font-size:13px}
.dm-ste-sum svg{color:var(--dm-ok);flex:none}
.dm-ste-box{display:flex;align-items:center;gap:6px;height:var(--dm-field-h);margin:0 var(--dm-s-1) var(--dm-s-1);padding:0 5px 0 var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-field-line);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.dm-ste-box{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.dm-ste-box:has(input:focus){box-shadow:inset 0 0 0 1px var(--dm-field-line-strong)}
.dm-ste-box input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:13px;color:var(--dm-fg)}
.dm-ste-box input::placeholder{color:var(--dm-muted)}
.dm-ste-go{width:30px;height:30px;border-radius:50%;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;flex:none;transition:background .2s}
.dm-ste-go[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}

